input.command:
cd /home/user/openai-nlogn-wiki/runs/G1; cat > exegenius/tasks/0002-background.answer.json <<'EOF'
{
  "summary": "The reader has an undergraduate computer science education: asymptotic analysis and recurrences, discrete mathematics (sets, functions, permutations, modular arithmetic, primes, gcd), a first course in linear algebra (vectors, matrices, rank, bases, subspaces, orthogonality, dot products), complex numbers and polynomial algebra, and basic multitape Turing machine computation including binary arithmetic. They have seen schoolbook multiplication and basic divide-and-conquer, but not the FFT's number-theoretic refinements, abstract algebra beyond rings of polynomials, tensor products, bilinear forms over finite fields, or the analytic number theory used for prime estimates.",
  "known": [
    {
      "name": "Logarithms and exponents",
      "aliases": ["log", "lg", "log base 2", "powers of two", "iterated logarithm", "exponent laws"],
      "gloss": "The base-2 logarithm and its rules (log of a product, powers and fractional exponents), including the ceiling form lg n and powers of log n such as (lg n)^(1-kappa)."
    },
    {
      "name": "Floor and ceiling functions",
      "aliases": ["floor", "ceiling", "rounding up", "rounding down", "integer part"],
      "gloss": "The functions that round a real number down or up to the nearest integer."
    },
    {
      "name": "Binary and radix integer representation",
      "aliases": ["positional notation", "base-B digits", "bit strings", "binary expansion", "radix", "digits in base B", "carries"],
      "gloss": "An integer is written as a sequence of digits in a base, with value the sum of digit times power of the base, and addition propagates carries from low to high digits."
    },
    {
      "name": "Schoolbook multiplication",
      "aliases": ["grade-school multiplication", "long multiplication", "quadratic multiplication", "naive multiplication"],
      "gloss": "The digit-by-digit multiplication algorithm taking time quadratic in the number of digits."
    },
    {
      "name": "Modular arithmetic and congruences",
      "aliases": ["residues", "mod", "congruence modulo q", "residue ring", "integers mod q", "remainder"],
      "gloss": "Arithmetic on integers reduced to remainders modulo a fixed positive integer q, where a is congruent to b mod q when q divides a - b."
    },
    {
      "name": "Primes, gcd and coprimality",
      "aliases": ["prime numbers", "greatest common divisor", "relatively prime", "pairwise coprime", "extended Euclidean algorithm", "modular inverse", "trial division", "divisibility"],
      "gloss": "Basic divisibility facts: primes, the gcd and coprimality of integers, the extended Euclidean algorithm giving Bezout coefficients and modular inverses, and primality testing by trial division."
    },
    {
      "name": "Sets, functions, bijections and permutations",
      "aliases": ["bijection", "permutation", "injective map", "index set", "Cartesian product", "subset", "finite sets", "partial permutation"],
      "gloss": "Standard discrete-mathematics vocabulary for finite sets, subsets, maps between them, one-to-one correspondences and rearrangements of an index set."
    },
    {
      "name": "Counting and binomial coefficients",
      "aliases": ["combinations", "n choose k", "subset counting", "Hamming weight", "popcount", "number of ones in a bit string"],
      "gloss": "Counting subsets of a given size by binomial coefficients, and the Hamming weight of a bit string as its number of ones."
    },
    {
      "name": "XOR and mod 2 arithmetic",
      "aliases": ["exclusive or", "addition mod 2", "bitwise XOR", "F_2", "GF(2)", "parity", "bitwise operations"],
      "gloss": "Bitwise exclusive-or, which is addition of bits modulo 2 (so parity is the sum of bits mod 2)."
    },
    {
      "name": "Vectors, matrices and linear maps",
      "aliases": ["matrix multiplication", "matrix-vector product", "identity matrix", "invertible matrix", "linear transformation", "standard basis vector", "linear combination", "transpose"],
      "gloss": "Column vectors, matrix addition and multiplication, invertibility, and the view of a matrix as a linear map that acts on coordinate vectors."
    },
    {
      "name": "Rank, bases and subspaces",
      "aliases": ["matrix rank", "linear independence", "basis", "span", "dimension", "subspace", "vector space", "Gaussian elimination", "row reduction", "elementary matrices", "nested subspaces"],
      "gloss": "Linear independence, bases, dimension of a subspace, the rank of a matrix as the dimension of its image, and row reduction by elementary operations."
    },
    {
      "name": "Dot product and orthogonality",
      "aliases": ["inner product", "orthogonal vectors", "orthonormal basis", "orthogonal complement", "norm of a vector", "orthogonal projection", "indicator vector"],
      "gloss": "The dot product of vectors, perpendicularity when it is zero, orthonormal bases, and the orthogonal complement of a subspace."
    },
    {
      "name": "Special matrices: triangular, diagonal and permutation matrices",
      "aliases": ["lower triangular matrix", "upper triangular matrix", "diagonal matrix", "permutation matrix", "diag", "projection matrix"],
      "gloss": "Matrices with zeros above or below the diagonal, matrices that are diagonal, and 0-1 matrices with a single one in each row and column that permute coordinates."
    },
    {
      "name": "Rational numbers and the number systems Q, R, C",
      "aliases": ["rationals", "real numbers", "rational matrices", "denominators", "integers Z"],
      "gloss": "The standard number systems of integers, rationals, reals and complex numbers, and arithmetic with fractions and denominators."
    },
    {
      "name": "Roots of unity",
      "aliases": ["primitive root of unity", "nth roots of unity", "e^{2 pi i / n}", "unit circle", "Euler's formula", "complex exponential"],
      "gloss": "The complex solutions of z^n = 1, equally spaced on the unit circle and given by powers of e^{2 pi i / n}."
    },
    {
      "name": "Triangle inequality and absolute value",
      "aliases": ["modulus bound", "maximum norm", "sup norm", "infinity norm", "disk bound", "error bound", "|a+b| <= |a|+|b|"],
      "gloss": "The inequality |a + b| <= |a| + |b| for absolute values and complex moduli, used with the maximum over entries to bound errors."
    },
    {
      "name": "Geometric series and recurrences",
      "aliases": ["geometric sum", "recurrence relation", "solving recurrences", "unrolling a recurrence", "master theorem", "divide and conquer", "recursion tree"],
      "gloss": "Summing a geometric series, and solving or bounding running-time recurrences of divide-and-conquer algorithms by unrolling them."
    },
    {
      "name": "Induction and proof by contradiction",
      "aliases": ["mathematical induction", "inductive proof", "proof technique", "lemma", "pigeonhole principle"],
      "gloss": "Standard proof techniques from discrete mathematics: induction, contradiction and simple counting arguments."
    },
    {
      "name": "Tape scans and constant-factor simulation on Turing machines",
      "aliases": ["linear-time scan", "tape head sweep", "work tape", "tape reversal", "copying a tape", "finite control with counter", "multitape simulation"],
      "gloss": "Basic multitape Turing machine programming: sweeping heads across a tape in linear time, copying data between tapes, and keeping bounded counters or carries in the finite control."
    },
    {
      "name": "Schoolbook and Karatsuba-style divide-and-conquer multiplication",
      "aliases": ["Karatsuba", "Toom-Cook", "splitting integers into halves"],
      "gloss": "Multiplying integers by splitting them into pieces and recombining partial products, giving exponents below 2 such as n^{log_2 3}."
    },
    {
      "name": "Polynomial evaluation and interpolation",
      "aliases": ["evaluation at points", "Horner's rule", "coefficient list", "degree of a polynomial", "polynomial division with remainder", "polynomial modulo x^q - 1"],
      "gloss": "Representing a polynomial by its coefficient list or its values at points, evaluating at a point, and reducing modulo a monic polynomial by remainder."
    },
    {
      "name": "Newton iteration for reciprocals",
      "aliases": ["Newton's method", "Newton reduction", "reciprocal approximation", "division by Newton iteration"],
      "gloss": "Newton's method, which repeatedly refines an approximation to a root (such as a reciprocal) with roughly doubling precision at each step."
    }
  ]
}
EOF
python3 -c "import json;json.load(open('exegenius/tasks/0002-background.answer.json'))" && exegenius submit 0002-background

